// ❌ OLD: Manual positioning requires reading geometry and writing
// coordinates — plus re-running on scroll/resize/reflow, handling
// flipping when it overflows, and cleanup. Lots of JS for a tooltip.
function positionPopover() {
  const r = btn.getBoundingClientRect(); // ❌ OLD: geometry read
  pop.style.left = `${r.right + 8}px`; // ❌ OLD: manual offset math
  pop.style.top = `${r.top}px`;
  // Flip if it overflows the viewport:
  if (r.right + pop.offsetWidth > innerWidth) {
    pop.style.left = `${r.left - pop.offsetWidth - 8}px`; // ❌ OLD: hand-rolled flip
  }
}
addEventListener('scroll', positionPopover, { passive: true });
addEventListener('resize', positionPopover);
positionPopover();
// And cleanup: remove both listeners later.

/* ✅ NEW: Declarative tethering. The popover is positioned against the
   button's anchor; the browser recomputes on scroll/resize/transform
   with no JS at all. */

.btn {
  anchor-name: --tip; /* ✅ NEW: register this element as an anchor */
}

.popover {
  position: absolute;
  position-anchor: --tip; /* ✅ NEW: tether to the anchor */
  inset-area: right; /* ✅ NEW: place in the right region of the anchor */
}

/* Flip when it would overflow:
   @position-try --flip { inset-area: left; }
   position-try-options: --flip;  -> the engine tries --flip first. */
